<script setup>
import { SHOPPING_APP_PAGE_EVENTS, SHOPPING_APP_PAGE_PROPS, localizeAppPage } from './shopping-app-page-contract'

const props = defineProps(SHOPPING_APP_PAGE_PROPS)
const emit = defineEmits(SHOPPING_APP_PAGE_EVENTS)
const localize = (zh, en) => localizeAppPage(props.languageBase, zh, en)
const searchChanged = (event) => emit('update:searchQuery', event.target.value)
</script>

<template>
  <main class="ikea-pages" :data-page="pageKey" data-testid="shopping-store-specific-page">
