      <div><button type="button" @click="emit('open-orders')">PROJECTS</button><button type="button" data-testid="shopping-page-cart" :aria-label="localize('房间清单', 'Room list')" @click="emit('open-cart')"><i class="fas fa-list-check"></i><b v-if="cartQuantity">{{ cartQuantity }}</b></button></div>
    </header>

    <template v-if="pageKey === 'category'">
